// scripts/gen-theme.mjs) so dark mode is a single class on <html>.
import themeColors from "./lib/theme-colors.json";

const config: Config = {
  darkMode: "class",
  content: ["./app/**/*.{js,ts,jsx,tsx,mdx}", "./components/**/*.{js,ts,jsx,tsx,mdx}", "./lib/**/*.{js,ts,jsx,tsx}"],
  theme: {
    extend: {
      colors: {
        ...themeColors,
        // Modal backdrops stay dark in both themes.
        scrim: "rgb(0 0 0 / <alpha-value>)",
      },
    },
  },
  plugins: [],
};

export default config;
